tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(90deg,#ff0000_0%,#ff0000_50%,#0000ff_50%,#0000ff_100%)]

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(90deg, #ff0000 0%, #ff0000 50%, #0000ff 50%, #0000ff 100%);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(90deg, #ff0000 0%, #ff0000 50%, #0000ff 50%, #0000ff 100%);
}

css-variables:
:root {
  --gradient-angle: 90deg;
  --gradient-color-1: #ff0000;
  --gradient-position-1: 0%;
  --gradient-color-2: #ff0000;
  --gradient-position-2: 50%;
  --gradient-color-3: #0000ff;
  --gradient-position-3: 50%;
  --gradient-color-4: #0000ff;
  --gradient-position-4: 100%;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1) var(--gradient-position-1), var(--gradient-color-2) var(--gradient-position-2), var(--gradient-color-3) var(--gradient-position-3), var(--gradient-color-4) var(--gradient-position-4));
}

/* Usage: background: var(--gradient); */

